  "mdp.model.title": "Un proceso de decisión de Markov con seis estados de desgaste",
  "mdp.model.tex": "\\begin{aligned} V(x) = \\min\\Bigl\\{\\, & c(x) + \\beta \\sum_{y=0}^{5} P_{xy}\\,V(y), && \\text{(mantener)}\\\\ & R + c(0) + \\beta \\sum_{y=0}^{5} P_{0y}\\,V(y) \\,\\Bigr\\} && \\text{(reemplazar)}\\end{aligned}",
